import React, { useEffect, useState } from "react";

import useApi from "../../../../hooks/useApi";
import { useNavigate,  } from "react-router-dom";
import departmentsApi from "../../../../api/departmentsApi";
import { Loading } from "../../../../components";
import RadiologyOrdersTable from "./RadiologyOrdersTable";
import hospitalsApi from "../../../../api/hospitals/hospitalsApi";


const columns = [
  { name: "Client", uid: "dependant_name" },
  { name: "Department", uid: "origin_department_title" },
  { name: "Reference", uid: "reference_number" },
  { name: "Status", uid: "status" },
  { name: "Examinations", uid: "examinations" },
  { name: "Total Price", uid: "order_total_price" },
  { name: "Date", uid: "created" },
  { name: "Actions", uid: "actions" },
];

function RadiologyOrdersList() {
  const [openInventoryFormModal, setopenInventoryFormModal] = useState(false);
  const navigate = useNavigate();
  const [selectedPhysiotherapyService, setselectedPhysiotherapyService] = useState();
  const [radiologyOrders, setradiologyOrders] = useState([]);
  const [data, setdata] = useState([]);
  const [modalTitle, setmodalTitle] = useState("");
  const [updated, setUpdated] = useState(false);

  const radiologyOrdersApi = useApi(hospitalsApi.hospitalStaffAction);





  const getRadiologyOrders = async (data) => {

    await radiologyOrdersApi.request({
      "action": "GetRadiologyOrders",

    });
  };

  useEffect(() => {
    if (radiologyOrdersApi.data) {
      if (radiologyOrdersApi.data.length) {
        setradiologyOrders(radiologyOrdersApi.data);
      }
    }
    console.log("radiologyOrdersApi.data",radiologyOrdersApi.data)
  }, [radiologyOrdersApi.data]);

  useEffect(() => {

    getRadiologyOrders();


  }, []);

  useEffect(() => {
    setdata(radiologyOrders);
  }, [radiologyOrders]);

  const handleEditAction = (item) => {
    setopenInventoryFormModal(true);
    setselectedPhysiotherapyService(item);
    setmodalTitle(`EDIT ${item.laboratory_service_title}`);
    setUpdated(false)
  };

  const handleAddAction = () => {
    setopenInventoryFormModal(true);
    setmodalTitle("Add new pathology service");
    setselectedPhysiotherapyService(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/systems/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    console.log("Item", item);
    navigate(`/systems/delete/${item.id}`);
  };

  useEffect(() => {
    if (radiologyOrdersApi.data && radiologyOrdersApi.data.length) {
      setradiologyOrders(radiologyOrdersApi.data);
    }
    console.log("laboratoryOrdersApi.data", radiologyOrdersApi.data);
  }, [radiologyOrdersApi.data]);

  useEffect(() => {
    if (updated === true) {

      getRadiologyOrders();
    }
  }, [updated]);

  //Filtering data
  useEffect(() => {
    setdata(radiologyOrders);
  }, [radiologyOrders]);

  const handleFilter = (e) => {
    const search_param = e;
    if (
      radiologyOrders &&
      radiologyOrders.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setdata(
        radiologyOrders.filter((x) => x.title.toLowerCase().includes(search_param))
      );
    } else {
      setdata(radiologyOrders);
    }
  };

  return radiologyOrdersApi.loading ? (
    <Loading loading={departmentsApi.loading} />
  ) : (
    <div className="mt-16 md:mt-2">


      <RadiologyOrdersTable
        title={"Radiology Orders"}
        data={data}
        columns={columns}
        editAction={handleEditAction}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        addAction={handleAddAction}
        handleFilter={handleFilter}
      />
    </div>
  );
}

export default RadiologyOrdersList;
